          word_idx_ff <= word_idx_reg + 2'd1;
          state_ff <= 4'( __const__STATE_DMA_MVOUT_READ );
        end
      end
    end
    else if ( state == 4'( __const__STATE_DMA_MVOUT_WRITE ) ) begin
      if ( send_to_dram_wr_req__val & send_to_dram_wr_req__rdy ) begin
        state_ff <= 4'( __const__STATE_DMA_MVOUT_WAIT );
      end
    end
    else if ( state == 4'( __const__STATE_DMA_MVOUT_WAIT ) ) begin
      if ( recv_from_dram_wr_resp__val & recv_from_dram_wr_resp__rdy ) begin
        dram_addr_ff <= dram_addr_reg + 16'd16;
        beat_ff <= 128'd0;
        word_idx_ff <= 2'd0;
        wr_mask_ff <= 16'd0;
        if ( words_left_reg == 8'd0 ) begin
          state_ff <= 4'( __const__STATE_DMA_DONE );
        end
        else
          state_ff <= 4'( __const__STATE_DMA_MVOUT_READ );
      end
    end
    else if ( state == 4'( __const__STATE_DMA_DONE ) ) begin
      if ( dma_done__val & dma_done__rdy ) begin
        state_ff <= 4'( __const__STATE_DMA_IDLE );
      end
    end
  end

  assign state = state_ff;
  assign opcode_reg = opcode_ff;
  assign dram_addr_reg = dram_addr_ff;
  assign spm_addr_reg = spm_addr_ff;
  assign words_left_reg = words_left_ff;
  assign tag_reg = tag_ff;
  assign beat_reg = beat_ff;
  assign word_idx_reg = word_idx_ff;
  assign wr_mask_reg = wr_mask_ff;

endmodule
